-- Create "webauthn_challenges" table
CREATE TABLE "webauthn_challenges" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "challenge" bytea NOT NULL, "binding_hash" bytea NOT NULL, "rp_id" text NOT NULL, "origin" text NOT NULL, "purpose" text NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "webauthn_binding_length" CHECK (octet_length(binding_hash) = 32), CONSTRAINT "webauthn_challenge_length" CHECK (octet_length(challenge) = 32), CONSTRAINT "webauthn_consumed_valid" CHECK ((consumed_at IS NULL) OR (isfinite(consumed_at) AND (consumed_at >= created_at) AND (consumed_at < expires_at))), CONSTRAINT "webauthn_expiry_valid" CHECK (isfinite(created_at) AND isfinite(expires_at) AND (expires_at > created_at) AND (expires_at <= (created_at + '00:05:00'::interval))), CONSTRAINT "webauthn_origin_length" CHECK ((length(origin) >= 1) AND (length(origin) <= 2048)), CONSTRAINT "webauthn_purpose_valid" CHECK (purpose = ANY (ARRAY['registration'::text, 'authentication'::text])), CONSTRAINT "webauthn_rp_length" CHECK ((length(rp_id) >= 1) AND (length(rp_id) <= 253)));
-- Create index "webauthn_challenges_expiry_idx" to table: "webauthn_challenges"
CREATE INDEX "webauthn_challenges_expiry_idx" ON "webauthn_challenges" ("expires_at");
